// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Lista eventos de auditoria append-only (multi-axis filter, cursor-paginated)
	// (GET /audit/events)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// Export filtered audit events as CSV or JSONL (signed URL, async if large)
	// (POST /audit/events/export)
	ExportAuditEvents(ctx context.Context, request ExportAuditEventsRequestObject) (ExportAuditEventsResponseObject, error)
	// Read the status of an audit export job
	// (GET /audit/events/export/{exportId})
	GetAuditExportStatus(ctx context.Context, request GetAuditExportStatusRequestObject) (GetAuditExportStatusResponseObject, error)
	// Download the rendered audit export payload via a signed token
	// (GET /audit/events/export/{exportId}/download)
	DownloadAuditExport(ctx context.Context, request DownloadAuditExportRequestObject) (DownloadAuditExportResponseObject, error)
	// List active sessions in the current tenant
	// (GET /auth/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// Revoke (force-logout) a specific session. Gate CapSessionManage.
	// (DELETE /auth/sessions/{sessionId})
	RevokeSession(ctx context.Context, request RevokeSessionRequestObject) (RevokeSessionResponseObject, error)
	// Composed Admin Center overview (KPI strip + presence + recent activity)
	// (GET /iam/admin/overview)
	GetIamAdminOverview(ctx context.Context, request GetIamAdminOverviewRequestObject) (GetIamAdminOverviewResponseObject, error)
	// List active area memberships for the current tenant
	// (GET /iam/area-memberships)
	ListAreaMemberships(ctx context.Context, request ListAreaMembershipsRequestObject) (ListAreaMembershipsResponseObject, error)
	// Grant an active area membership
	// (POST /iam/area-memberships)
	GrantAreaMembership(ctx context.Context, request GrantAreaMembershipRequestObject) (GrantAreaMembershipResponseObject, error)
	// Revoke an active area membership
	// (DELETE /iam/area-memberships/{user_id}/{area_code})
	RevokeAreaMembership(ctx context.Context, request RevokeAreaMembershipRequestObject) (RevokeAreaMembershipResponseObject, error)
	// List capability registry (read-only)
	// (GET /iam/capabilities)
	ListCapabilities(ctx context.Context, request ListCapabilitiesRequestObject) (ListCapabilitiesResponseObject, error)
	// Tenant KPI snapshot for the Overview strip
	// (GET /iam/kpi)
	GetKpi(ctx context.Context, request GetKpiRequestObject) (GetKpiResponseObject, error)
	// Online presence snapshot (HTTP fallback when WebSocket unavailable)
	// (GET /iam/presence/snapshot)
	GetPresenceSnapshot(ctx context.Context, request GetPresenceSnapshotRequestObject) (GetPresenceSnapshotResponseObject, error)
	// List role-capability matrix rows (read-only)
	// (GET /iam/role-capabilities)
	ListRoleCapabilities(ctx context.Context, request ListRoleCapabilitiesRequestObject) (ListRoleCapabilitiesResponseObject, error)
	// List canonical tenant roles (read-only)
	// (GET /iam/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// Tenant consumption snapshot (seats, storage, API, active users)
	// (GET /iam/usage)
	GetUsage(ctx context.Context, request GetUsageRequestObject) (GetUsageResponseObject, error)
	// List tenant users (cursor-paginated, filterable)
	// (GET /iam/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// Cria usuario interno com credencial local inicial (legacy; prefer POST /iam/users/invite)
	// (POST /iam/users)
	CreateManagedUser(ctx context.Context, request CreateManagedUserRequestObject) (CreateManagedUserResponseObject, error)
	// Bulk action over a set of users (activate, deactivate, unlock, force-logout)
	// (POST /iam/users/bulk)
	BulkUsers(ctx context.Context, request BulkUsersRequestObject) (BulkUsersResponseObject, error)
	// Invite a new user (server-generated temp password, must change on first login)
	// (POST /iam/users/invite)
	InviteUser(ctx context.Context, request InviteUserRequestObject) (InviteUserResponseObject, error)
	// Atomic metadata + tenant role update (single tx)
	// (PATCH /iam/users/{userId})
	PatchUser(ctx context.Context, request PatchUserRequestObject) (PatchUserResponseObject, error)
	// List area memberships for a user
	// (GET /iam/users/{userId}/memberships)
	ListMemberships(ctx context.Context, request ListMembershipsRequestObject) (ListMembershipsResponseObject, error)
	// Admin password reset (forces must-change-on-first-login)
	// (POST /iam/users/{userId}/reset-password)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// Cria/atualiza usuario IAM e atribui role
	// (POST /iam/users/{userId}/roles)
	UpsertUserRole(ctx context.Context, request UpsertUserRoleRequestObject) (UpsertUserRoleResponseObject, error)
	// Reconcilia o conjunto de roles de um usuario interno
	// (PUT /iam/users/{userId}/roles)
	ReplaceUserRoles(ctx context.Context, request ReplaceUserRolesRequestObject) (ReplaceUserRolesResponseObject, error)
	// Clear operational lock + failed-login counter for a user
	// (POST /iam/users/{userId}/unlock)
	UnlockUser(ctx context.Context, request UnlockUserRequestObject) (UnlockUserResponseObject, error)
	// Current account lockouts (locked-until window)
	// (GET /security/lockouts)
	ListLockouts(ctx context.Context, request ListLockoutsRequestObject) (ListLockoutsResponseObject, error)
	// MFA enrollment coverage by tenant + by role
	// (GET /security/mfa-coverage)
	GetMfaCoverage(ctx context.Context, request GetMfaCoverageRequestObject) (GetMfaCoverageResponseObject, error)
	// Anomaly cards (repeated-failed-login, new-device-login, lockout-spike, off-hours-admin-action)
	// (GET /security/signals)
	ListSecuritySignals(ctx context.Context, request ListSecuritySignalsRequestObject) (ListSecuritySignalsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

